// Runs in the page before it loads. It hands the page the first-run setup token (generated by the app, so nobody
// has to copy it from a terminal), and nothing else: no Node, no file access.
const { contextBridge, ipcRenderer } = require('electron');

contextBridge.exposeInMainWorld('proculusDesktop', {
	setupToken: ipcRenderer.sendSync('proculus:token'),
	simulation: ipcRenderer.sendSync('proculus:simulation'),
});
